      "id": "rc:2718514479",
      "kind": "correctness",
      "harm": "Disabling network activity drops existing anchors on a subsequent clean shutdown if no new connections were made.",
      "quote": "This seems like a bug... Maybe we should re-save the original anchors if there's no new ones at a clean shutdown?",
      "blocking": false,
      "status": "resolved",
      "author_replies": [
        "rc:2731809019",
        "c:4143178865"
      ],
      "fix_pushed": true,
      "settled_by_id": "c:4143178865",
      "settled_by_quote": "I just changed the approach of this PR and changed PR title and description. It addresses concerns like https://github.com/bitcoin/bitcoin/pull/34213#discussion_r2718514479."
    },
    {
      "id": "rc:3064766043",
      "kind": "safety",
      "harm": "A race condition between setting fNetworkActive to false and socket disconnection allows ThreadSocketHandler to clear connections before block-relay peers are captured into m_anchors.",
      "quote": "currently there is a data race, you should first save the anchors, and only then set `fNetworkActive = active`",
      "blocking": false,
      "status": "resolved",
      "author_replies": [
        "rc:3074479976",
        "c:4238164581"
      ],
      "fix_pushed": true,
      "settled_by_id": "c:4238164581",
      "settled_by_quote": "Fixed data race when disabling the network and saving the anchors."
    },
    {
      "id": "rc:3978006683",
      "kind": "correctness",
      "harm": "ThreadOpenConnections continues popping and discarding anchors while network activity is disabled, leading to empty anchors upon shutdown.",
      "quote": "ThreadOpenConnections() still consumes m_anchors while networking is disabled. It pops an address before calling OpenNetworkConnection(), which then returns because fNetworkActive is false.",
      "blocking": false,
      "status": "resolved",
      "author_replies": [
        "rc:3985114884",
        "rc:3985129345",
        "c:5628027086"
      ],
      "fix_pushed": true,
      "settled_by_id": "r:5197567648",
      "settled_by_quote": "Looks pretty nice to me now, thanks for addressing my comments."
    },
    {
      "id": "rc:3985494910",
      "kind": "correctness",
      "harm": "Anchors saved on network deactivation were not capped to the oldest peers, allowing a newly added block-relay peer to displace older anchors.",
      "quote": "GetCurrentBlockRelayOnlyConns() returns peers in connection order, while ThreadOpenConnections() consumes anchors from the back... Including a temporary third peer therefore lets it take the oldest anchor’s place after a network toggle.",
      "blocking": false,
      "status": "resolved",
      "author_replies": [
        "rc:3989624810",
        "c:5635220642"
      ],
      "fix_pushed": true,
      "settled_by_id": "c:5635220642",
      "settled_by_quote": "Force-pushed addressing https://github.com/bitcoin/bitcoin/pull/34213#discussion_r3985494910."
    }
